mat2 rotate(float a)
{
	float c = cos(a);
	float s = sin(a);
	return mat2(c, s, -s, c);
}
vec3 hsv2rgb_smooth( in vec3 c )
{
    vec3 rgb = clamp( abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0 );

	rgb = rgb*rgb*(3.0-2.0*rgb); // cubic smoothing	

	return c.z * mix( vec3(1.0), rgb, c.y);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	//get coords and direction
	vec2 uv=fragCoord.xy/iResolution.xy-.5;


	//mouse rotation

	vec2 uv2 = (gl_FragCoord.xy / iResolution.xy) + 1.; // Coordinate UV normali
float waveAmplitude = 0.05; // Ampiezza delle onde
float waveFrequency = 20.0; // Frequenza delle onde

// Distorsione per l'effetto onde
vec2 offset = vec2(perlin_noise(uv2 * waveFrequency + time * 1.,1.), perlin_noise(uv2 * waveFrequency + time * 1.,1.))* waveAmplitude;
vec2 distortedUv = uv2+offset;


float t = iTime * .1 + ((.25 + .05 * sin(iTime * .1))/(length(uv.xy) + .07)) * 2.2;
	float si = sin(t);
	float co = cos(t);
	mat2 ma = mat2(co, si, -si, co);
    vec2 uv3 = uv;
uv3.y *= resolution.y/resolution.x;
uv3/=2.;

uv3 = vec2(atan(uv3.x,uv3.y),length(uv3));
