float cir = cos((abs((uv3.y-time)*5.)) + sin(smoothnoise(uv3.x*5.)))+15.;
col = palette(cir);
col *= palette(0.);
float lines = (sin((uv3.x-uv3.y+time)*6.)/6.);
col /= palette2(lines*.8);

	float v1, v2, v3;
	v1 = v2 = v3 = 0.0;

	float s2 = 0.0;
	for (int i = 0; i < 90; i++)
	{
		vec3 p = s2 * vec3(uv, 1.0)*col*o.xyz;

		p += vec3(.22, .3, s2 - 1.5 - sin(iTime * .13) * .1);
		for (int i = 0; i < 8; i++)	p = abs(p) / dot(p,p) - 0.659;
		v1 += dot(p,p) * .0015 * (1.8 + sin(length(uv2.xy * 13.0) + .5  - iTime * .2));
		v2 += dot(p,p) * .0013 * (1.5 + sin(length(uv2.xy * 14.5) + 1.2 - iTime * .3));
		v3 += length(p.xy*10.) * .0003;
		s2  += .035;
	}

	float len = length(uv);
