					(v1 + v3) * .3,
					 v2) + smoothstep(0.2, .0, len) * .85 + smoothstep(.0, .6, v3) * .3;


	vec2 aspect = resolution.xy / resolution.y;
	uv1 = ( gl_FragCoord.xy / resolution.y ) - aspect / 2.0;
	float _d =  1.0-length(uv3);
	uv1 *= 18.0 ;
	uv1 -= vec2(-7., -1.5);


